<?php require 'includes/bootstrap.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $roll=trim($_POST['roll_no']??'');$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$degree=trim($_POST['degree']??'');$pw=$_POST['password']??''; if($pw!==($_POST['confirm_password']??'')){flash('Passwords do not match.');}else{try{$q=$pdo->prepare('INSERT INTO student(roll_no,name,email,password,degree,is_approved) VALUES(?,?,?,?,?,0)');$q->execute([$roll,$name,$email,password_hash($pw,PASSWORD_DEFAULT),$degree]);flash('Registration submitted. Wait for admin approval.');go('student_login.php');}catch(PDOException $e){flash('Registration failed. Roll number or email may already exist.');}}} page_start('Student Registration'); ?>
<div class="vc-card"><h2>Student Registration</h2><form method="post"><?php field('roll_no','Roll Number');field('name','Full Name');field('email','Email','email');field('degree','Degree / Programme');field('password','Password','password');field('confirm_password','Confirm Password','password');?><button class="btn btn-primary">Register</button></form></div><?php page_end(); ?>
